/* Parallel AES-GCM (12-byte nonce) using OpenSSL AES-CTR + PCLMUL GHASH.
 * Build: cc -O3 -shared -fPIC -o gcm_fast.so gcm_fast.c -lcrypto -I/usr/local/include -L/usr/local/lib
