# GCM polynomial reduction in pure python, two conventions, compare to scalar gmul
R = 0xE1 << 120  # reflected reduction constant used by scalar

def gmul_scalar(a, b):
    X = int.from_bytes(a, 'big')
    Y = int.from_bytes(b, 'big')
    Z = 0
    for i in range(128):
        if (Y >> (127-i)) & 1:
            Z ^= X
        if X & 1:
            X = (X >> 1) ^ R
        else:
            X >>= 1
    return Z.to_bytes(16, 'big')

def reflect128(x):
    # reverse all 128 bits
    y = 0
    for i in range(128):
        if (x >> i) & 1:
            y |= 1 << (127-i)
    return y

# bit-reverse within each byte (GCM reflection is per-byte bit reverse, NOT full 128 reverse)
def reflect_bytes(data: bytes) -> int:
    x = 0
    for i, by in enumerate(data):
        rb = int('{:08b}'.format(by)[::-1], 2)
        x = (x << 8) | rb
    return x

