hi = int.from_bytes(raw.raw[16:], 'little')
prod = lo | (hi << 128)
print("raw prod bits", prod.bit_length())

# Reduce prod modulo x^128 + x^7 + x^2 + x + 1, where prod bits are little-endian (bit 0 = x^0)
POLY = (1 << 128) | (1 << 7) | (1 << 2) | (1 << 1) | 1
def reduce_le(prod):
    # for bits 255..128, fold
    for i in range(255, 127, -1):
        if (prod >> i) & 1:
            prod ^= POLY << (i - 128)
    return prod & ((1<<128)-1)

