    __m128i hi = _mm_and_si128(_mm_srli_epi16(x, 4), _mm_set1_epi8(0x0f));
    lo = _mm_shuffle_epi8(luth, lo);
    hi = _mm_shuffle_epi8(luth, hi);
    /* result = (bitrev(lo nibble) << 4) | bitrev(hi nibble) */
    return _mm_or_si128(_mm_slli_epi16(lo, 4), hi);
}

static inline __m128i gmul(__m128i a, __m128i b) {
    a = brev_bytes(a);
    b = brev_bytes(b);
    __m128i t0 = _mm_clmulepi64_si128(a, b, 0x00);
    __m128i t1 = _mm_clmulepi64_si128(a, b, 0x11);
    __m128i t2 = _mm_xor_si128(_mm_clmulepi64_si128(a, b, 0x01),
                               _mm_clmulepi64_si128(a, b, 0x10));
    __m128i t3 = _mm_slli_si128(t2, 8);
    t2 = _mm_srli_si128(t2, 8);
    __m128i X0 = _mm_xor_si128(t0, t3); /* low 128, bit 0 = x^0 */
    __m128i X1 = _mm_xor_si128(t1, t2); /* high 128, bit 0 = x^128 */

    /* Reduce high half: for the polynomial p(x) = x^128 + x^7 + x^2 + x + 1,
     * x^128 = x^7 + x^2 + x + 1, so x^(128+k) = x^k * (x^7+x^2+x+1).
     * X1 represents coefficients of x^128 .. x^255. Fold:
     *   X0 ^= X1 << 7 ^ X1 << 2 ^ X1 << 1 ^ X1
     * with 128-bit shifts (cross-lane). Bits shifted past bit 127 from X1<<7
     * (i.e. x^128 .. x^134) must be folded again.
     *
     * 128-bit left shift by s (s<64): 
     *   low lane << s, high lane = (high<<s) | (low >> (64-s))
     */
    #define SHL128(V, S) ({ \
        __m128i _v = (V); \
        __m128i _lo = _mm_slli_epi64(_v, (S)); \
        __m128i _hi = _mm_srli_epi64(_v, (64-(S))); \
        _hi = _mm_slli_si128(_hi, 8); /* move low-lane overflow into high lane, high-lane overflow discarded (we handle separately) */ \
        /* wait: srli of high lane also produced bits that should go to bit 128+, which we need. */ \
        _mm_or_si128(_lo, _hi); \
    })

    /* Do the fold carefully in 64-bit lanes so we can capture the overflow. */
    /* X1 = [H | L] meaning value = L + (H<<64), and this multiplies x^128. */
    /* We need X0 ^= X1 ^ (X1<<1) ^ (X1<<2) ^ (X1<<7), all mod 2, as 128-bit,
     * PLUS a second reduction of the bits that overflow past bit 127.
     * Overflow of X1<<7 is only the top 7 bits of X1 (bits 121..127 of the 128-bit X1),
     * which land at x^128 .. x^134. Their contribution after a second fold is
     * those 7 bits shifted to positions 0..6, 1..7, 2..8, 7..13. Since they are
     * only 7 bits, a second overflow cannot occur (7+7=14 < 128).
     */

    __m128i fold = X1;
    /* X1 << 1 */
    {
        __m128i lo = _mm_slli_epi64(X1, 1);
        __m128i carry = _mm_srli_epi64(X1, 63);
        carry = _mm_slli_si128(carry, 8);          /* low-lane carry -> high lane; high-lane carry discarded into overflow */
        fold = _mm_xor_si128(fold, _mm_or_si128(lo, carry));
    }
    /* X1 << 2 */
    {
        __m128i lo = _mm_slli_epi64(X1, 2);
        __m128i carry = _mm_srli_epi64(X1, 62);
        carry = _mm_slli_si128(carry, 8);
        fold = _mm_xor_si128(fold, _mm_or_si128(lo, carry));
    }
    /* X1 << 7 */
    {
        __m128i lo = _mm_slli_epi64(X1, 7);
        __m128i carry = _mm_srli_epi64(X1, 57);
        carry = _mm_slli_si128(carry, 8);
        fold = _mm_xor_si128(fold, _mm_or_si128(lo, carry));
    }
    X0 = _mm_xor_si128(X0, fold);

    /* Second reduction: overflow bits.
     * For shift s in {0,1,2,7}: bits of X1 at positions (128-s)..127 overflow.
     * Those bits are the top s bits of the high lane of X1.
     * They contribute (overflow_value) * (x^7+x^2+x+1) at the low end,
     * where overflow_value's bit 0 corresponds to x^128 (i.e. the bit that
     * shifted exactly 128 positions).
     *
     * overflow bit from (X1 << s) at position 128+k comes from X1 bit (128 - s + k)? 
     * X1 bit j (0..127) shifted left by s lands at bit j+s. It overflows if j+s >= 128,
     * i.e. j >= 128-s, and lands at overflow position (j+s-128).
     * So overflow_s = X1 >> (128-s), a value of s bits.
     * Total overflow polynomial = (X1>>128)<<0  [none, s=0 has no overflow]
     *   ^ (X1>>127) ^ (X1>>126) ^ (X1>>121)
     * Then fold overflow the same way: ov ^ (ov<<1) ^ (ov<<2) ^ (ov<<7).
     */
    __m128i ov = _mm_setzero_si128();
    /* X1 >> 127: top 1 bit */
    {
        __m128i t = _mm_srli_epi64(X1, 63);          /* each lane >> 63 */
        /* high lane's bit0 is X1 bit 127; move it to low lane bit 0. low lane bit0 is X1 bit 63, not part of >>127. */
        __m128i hi = _mm_srli_si128(t, 8);
        ov = _mm_xor_si128(ov, hi);
    }
    /* X1 >> 126: top 2 bits */
    {
        __m128i t = _mm_srli_epi64(X1, 62);
        __m128i hi = _mm_srli_si128(t, 8);
        /* also bit 63 of low? no: >>126 only involves bits 126,127 which are in high lane. */
        ov = _mm_xor_si128(ov, hi);
    }
    /* X1 >> 121: top 7 bits, all in high lane (bits 121..127) */
    {
        __m128i t = _mm_srli_epi64(X1, 57); /* 64-57=7, high lane >> 57 gives bits 121..127 in low 7 bits */
        __m128i hi = _mm_srli_si128(t, 8);
        ov = _mm_xor_si128(ov, hi);
    }
    /* fold ov (only low few bits set) */
    {
        __m128i f = ov;
        f = _mm_xor_si128(f, _mm_slli_epi64(ov, 1));
        f = _mm_xor_si128(f, _mm_slli_epi64(ov, 2));
        f = _mm_xor_si128(f, _mm_slli_epi64(ov, 7));
        X0 = _mm_xor_si128(X0, f);
    }
    return brev_bytes(X0);
}

void gcm_gmul(uint8_t out[16], const uint8_t a[16], const uint8_t b[16]) {
    __m128i r = gmul(_mm_loadu_si128((const __m128i*)a), _mm_loadu_si128((const __m128i*)b));
    _mm_storeu_si128((__m128i*)out, r);
}

void gcm_ghash(uint8_t out[16], const uint8_t *data, size_t len, const uint8_t H[16]) {
    __m128i h = _mm_loadu_si128((const __m128i*)H);
    __m128i y = _mm_setzero_si128();
    size_t i = 0;
    for (; i + 16 <= len; i += 16) {
        y = _mm_xor_si128(y, _mm_loadu_si128((const __m128i*)(data + i)));
        y = gmul(y, h);
    }
    if (i < len) {
        uint8_t tmp[16] = {0};
        memcpy(tmp, data + i, len - i);
        y = _mm_xor_si128(y, _mm_loadu_si128((const __m128i*)tmp));
        y = gmul(y, h);
    }
    _mm_storeu_si128((__m128i*)out, y);
}
