#include <wmmintrin.h>
#include <emmintrin.h>
#include <tmmintrin.h>
#include <smmintrin.h>

/*
 * Verified GHASH multiply: bit-reverse both operands' bytes, PCLMUL, reduce
 * mod x^128+x^7+x^2+x+1 in little-endian coefficient order, bit-reverse back.
 *
 * To make the bulk loop cheaper we pre-reverse H once. Each block then needs
 * only one byte-bit-reversal instead of two, plus the reduction.
 */

static inline __m128i brev_bytes(__m128i x) {
    const __m128i lut = _mm_setr_epi8(
        0x00,0x08,0x04,0x0c,0x02,0x0a,0x06,0x0e,
        0x01,0x09,0x05,0x0d,0x03,0x0b,0x07,0x0f);
    __m128i lo = _mm_and_si128(x, _mm_set1_epi8(0x0f));
    __m128i hi = _mm_and_si128(_mm_srli_epi16(x, 4), _mm_set1_epi8(0x0f));
    lo = _mm_shuffle_epi8(lut, lo);
    hi = _mm_shuffle_epi8(lut, hi);
    return _mm_or_si128(_mm_slli_epi16(lo, 4), hi);
}

/* a, b are already byte-bit-reversed. Result is byte-bit-reversed product. */
static inline __m128i mul_reflected(__m128i a, __m128i b) {
    __m128i t0 = _mm_clmulepi64_si128(a, b, 0x00);
    __m128i t1 = _mm_clmulepi64_si128(a, b, 0x11);
    __m128i t2 = _mm_xor_si128(_mm_clmulepi64_si128(a, b, 0x01),
