    _mm_storeu_si128((__m128i*)out, brev_bytes(c->y));
}

void gcm_ghash(uint8_t out[16], const uint8_t *data, size_t len, const uint8_t H[16]) {
    ghash_ctx c;
    ghash_init(&c, H);
    ghash_update(&c, data, len);
    ghash_final(&c, out);
}

void gcm_gmul(uint8_t out[16], const uint8_t a[16], const uint8_t b[16]) {
    __m128i ar = brev_bytes(_mm_loadu_si128((const __m128i*)a));
    __m128i br = brev_bytes(_mm_loadu_si128((const __m128i*)b));
    _mm_storeu_si128((__m128i*)out, brev_bytes(mul_reflected(ar, br)));
}

/* Parallel GHASH: each thread computes GHASH of its slice (as if it started
 * from zero). The caller multiplies by H^{blocks_after} and xors. */
#include <pthread.h>

typedef struct {
    const uint8_t *data;
    size_t len;
    __m128i H;
    uint8_t out[16];
} ghash_job;

static void *ghash_thread(void *arg) {
    ghash_job *j = arg;
    ghash_ctx c;
    c.H = j->H;
    c.y = _mm_setzero_si128();
    ghash_update(&c, j->data, j->len);
    _mm_storeu_si128((__m128i*)j->out, brev_bytes(c.y));
    return NULL;
}

/* Compute GHASH of data with nthreads threads. len may be any size; the last
 * partial block is handled by the last thread. Returns GCM-representation GHASH.
 * H_reflected is the already-reversed H (16 bytes, raw xmm form). */
void ghash_parallel(uint8_t out[16], const uint8_t *data, size_t len,
                    const uint8_t H[16], int nthreads) {
    if (nthreads < 1) nthreads = 1;
    if (len < 1024*1024 || nthreads == 1) {
        gcm_ghash(out, data, len, H);
        return;
    }
    size_t blocks = (len + 15) / 16;
    /* split on block boundaries */
    size_t base = blocks / nthreads;
    ghash_job jobs[16];
    pthread_t th[16];
    if (nthreads > 16) nthreads = 16;
    __m128i Href = brev_bytes(_mm_loadu_si128((const __m128i*)H));
    uint8_t Hraw[16];
    _mm_storeu_si128((__m128i*)Hraw, Href);

    size_t off = 0;
    int actual = 0;
    for (int t = 0; t < nthreads; t++) {
        size_t nb = (t == nthreads - 1) ? (blocks - off / 16) : base;
        size_t nbytes = nb * 16;
        if (t == nthreads - 1) nbytes = len - off;
        if (nbytes == 0) break;
        jobs[t].data = data + off;
        jobs[t].len = nbytes;
        jobs[t].H = Href;
        off += nbytes;
        actual++;
    }
    for (int t = 0; t < actual; t++) pthread_create(&th[t], NULL, ghash_thread, &jobs[t]);
    for (int t = 0; t < actual; t++) pthread_join(th[t], NULL);

    /* Combine: GHASH = sum_t GHASH_t * H^{blocks_after_t}
     * GHASH_t treats its last block as * H^1, so blocks_after is the number of
     * blocks strictly after this slice (NOT including a length block; caller
     * handles that). */
    /* We do the combination in C using gmul. */
    uint8_t acc[16] = {0};
    /* process from the last slice backward so the running multiplier is easy:
     * start from last slice (already *H^1 .. *H^{L}), xor into acc, then for
     * each previous slice multiply acc by H^{slice_blocks} and xor that slice.
     */
    for (int t = actual - 1; t >= 0; t--) {
        size_t nb = (jobs[t].len + 15) / 16;
        if (t != actual - 1) {
            /* acc *= H^{nb_of_later}? No: acc currently holds later slices'
             * contribution with their own internal powers relative to the end
             * of the later part. We need to multiply acc by H^{nb} where nb is
             * THIS slice's block count, so that later blocks shift up by nb.
             * Do that before xoring this slice. */
            /* multiply acc by H^nb */
            uint8_t pow[16];
            /* compute H^nb via square-and-multiply using gcm_gmul */
            uint8_t base[16], res[16];
            memcpy(base, H, 16);
            memset(res, 0, 16); res[0] = 0x80; /* identity */
            size_t e = nb;
            uint8_t tmp[16];
            while (e) {
                if (e & 1) {
                    gcm_gmul(tmp, res, base);
                    memcpy(res, tmp, 16);
                }
                gcm_gmul(tmp, base, base);
                memcpy(base, tmp, 16);
                e >>= 1;
            }
            gcm_gmul(tmp, acc, res);
            memcpy(acc, tmp, 16);
        }
        for (int i = 0; i < 16; i++) acc[i] ^= jobs[t].out[i];
    }
    memcpy(out, acc, 16);
}
