 * 0: inputs brev, redA, output brev
 * 1: inputs brev, redB, output brev
 * 2: inputs bswap, redA, output bswap
 * 3: inputs bswap, redB, output bswap
 * 4: inputs brev+bswap, redA, output bswap+brev
 * 5: inputs brev+bswap, redB, output bswap+brev
 * 6: inputs brev, redA on swapped halves, output brev
 * 7: inputs bswap, redA on swapped, output bswap
 * 8: inputs brev+bswap, redA on swapped, output bswap+brev
 * 9: inputs raw, redA, output raw
 * 10: inputs raw, redB, output raw
