void tryv(uint8_t out[16], const uint8_t A[16], const uint8_t B[16], int v) {
    __m128i a = _mm_loadu_si128((const __m128i*)A);
    __m128i b = _mm_loadu_si128((const __m128i*)B);
    int swap_halves = 0, do_brev = 0, do_bswap = 0, which = 0;
    switch (v) {
    case 0: do_brev=1; which=0; break;
    case 1: do_brev=1; which=1; break;
    case 2: do_bswap=1; which=0; break;
    case 3: do_bswap=1; which=1; break;
    case 4: do_brev=1; do_bswap=1; which=0; break;
    case 5: do_brev=1; do_bswap=1; which=1; break;
    case 6: do_brev=1; which=0; swap_halves=1; break;
    case 7: do_bswap=1; which=0; swap_halves=1; break;
    case 8: do_brev=1; do_bswap=1; which=0; swap_halves=1; break;
    case 9: which=0; break;
    case 10: which=1; break;
    case 11: do_brev=1; which=1; swap_halves=1; break;
    case 12: do_bswap=1; which=1; swap_halves=1; break;
    case 13: do_brev=1; do_bswap=1; which=1; swap_halves=1; break;
    }
    if (do_brev) { a = brev(a); b = brev(b); }
    if (do_bswap) { a = bswap16(a); b = bswap16(b); }
