    fold = _mm_xor_si128(fold, _mm_or_si128(_mm_slli_epi64(hi, 1), _mm_slli_si128(_mm_srli_epi64(hi, 63), 8)));
    fold = _mm_xor_si128(fold, _mm_or_si128(_mm_slli_epi64(hi, 2), _mm_slli_si128(_mm_srli_epi64(hi, 62), 8)));
    fold = _mm_xor_si128(fold, _mm_or_si128(_mm_slli_epi64(hi, 7), _mm_slli_si128(_mm_srli_epi64(hi, 57), 8)));
    lo = _mm_xor_si128(lo, fold);
    __m128i ov = _mm_srli_si128(_mm_srli_epi64(hi, 63), 8);
    ov = _mm_xor_si128(ov, _mm_srli_si128(_mm_srli_epi64(hi, 62), 8));
    ov = _mm_xor_si128(ov, _mm_srli_si128(_mm_srli_epi64(hi, 57), 8));
    __m128i f = _mm_xor_si128(ov, _mm_slli_epi64(ov, 1));
    f = _mm_xor_si128(f, _mm_slli_epi64(ov, 2));
    f = _mm_xor_si128(f, _mm_slli_epi64(ov, 7));
    return _mm_xor_si128(lo, f);
}

/* 8 independent multiplies, inputs already reversed. */
static __m128i ghash8(const uint8_t *data, size_t nblocks, __m128i Hrev) {
    __m128i P[8];
    P[0] = Hrev;
    for (int i = 1; i < 8; i++) P[i] = mul_r(P[i-1], Hrev);
    /* P[k] = H^{k+1}. For aggregation we want b0*H^8 + ... + b7*H. */
    __m128i y = _mm_setzero_si128();
    size_t i = 0;
    for (; i + 8 <= nblocks; i += 8) {
        __m128i acc = mul_r(y, P[7]); /* * H^8 */
        for (int k = 0; k < 8; k++) {
            __m128i blk = brev(_mm_loadu_si128((const __m128i*)(data + (i+k)*16)));
            acc = _mm_xor_si128(acc, mul_r(blk, P[7-k]));
        }
        y = acc;
    }
    for (; i < nblocks; i++) {
        __m128i blk = brev(_mm_loadu_si128((const __m128i*)(data + i*16)));
        y = mul_r(_mm_xor_si128(y, blk), Hrev);
    }
    return y;
}

/* Same but data pre-reversed into a buffer (measures mul-only throughput). */
static __m128i ghash8_pre(const __m128i *blocks, size_t nblocks, __m128i Hrev) {
    __m128i P[8];
    P[0] = Hrev;
    for (int i = 1; i < 8; i++) P[i] = mul_r(P[i-1], Hrev);
    __m128i y = _mm_setzero_si128();
    size_t i = 0;
    for (; i + 8 <= nblocks; i += 8) {
        __m128i acc = mul_r(y, P[7]);
        for (int k = 0; k < 8; k++) acc = _mm_xor_si128(acc, mul_r(blocks[i+k], P[7-k]));
        y = acc;
    }
    return y;
}

int main() {
    size_t n = 60*1024*1024/16;
    uint8_t *data = malloc(n*16);
    memset(data, 0x5a, n*16);
    __m128i H = _mm_set1_epi8(0x3c);
    struct timespec t0,t1;
    clock_gettime(CLOCK_MONOTONIC,&t0);
    volatile __m128i y = ghash8(data, n, H);
    clock_gettime(CLOCK_MONOTONIC,&t1);
    double dt=(t1.tv_sec-t0.tv_sec)+(t1.tv_nsec-t0.tv_nsec)/1e9;
    printf("with brev %.4f s %.2f GB/s\n", dt, n*16/dt/1e9);
    (void)y;
    free(data);
    return 0;
}
EOF
