#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <time.h>
#include <wmmintrin.h>
#include <emmintrin.h>
#include <tmmintrin.h>
#include <smmintrin.h>

static inline __m128i brev(__m128i x) {
    const __m128i lut = _mm_setr_epi8(0x00,0x08,0x04,0x0c,0x02,0x0a,0x06,0x0e,0x01,0x09,0x05,0x0d,0x03,0x0b,0x07,0x0f);
    __m128i lo = _mm_shuffle_epi8(lut, _mm_and_si128(x, _mm_set1_epi8(0x0f)));
    __m128i hi = _mm_shuffle_epi8(lut, _mm_and_si128(_mm_srli_epi16(x, 4), _mm_set1_epi8(0x0f)));
    return _mm_or_si128(_mm_slli_epi16(lo, 4), hi);
}

typedef struct { __m128i lo, hi; } prod_t;

static inline prod_t clmul( __m128i a, __m128i b) {
    prod_t p;
    __m128i mid = _mm_xor_si128(_mm_clmulepi64_si128(a, b, 0x01), _mm_clmulepi64_si128(a, b, 0x10));
    p.lo = _mm_xor_si128(_mm_clmulepi64_si128(a, b, 0x00), _mm_slli_si128(mid, 8));
    p.hi = _mm_xor_si128(_mm_clmulepi64_si128(a, b, 0x11), _mm_srli_si128(mid, 8));
    return p;
}
static inline __m128i reduce(prod_t p) {
    __m128i hi = p.hi, lo = p.lo;
    __m128i fold = hi;
    fold = _mm_xor_si128(fold, _mm_or_si128(_mm_slli_epi64(hi, 1), _mm_slli_si128(_mm_srli_epi64(hi, 63), 8)));
    fold = _mm_xor_si128(fold, _mm_or_si128(_mm_slli_epi64(hi, 2), _mm_slli_si128(_mm_srli_epi64(hi, 62), 8)));
    fold = _mm_xor_si128(fold, _mm_or_si128(_mm_slli_epi64(hi, 7), _mm_slli_si128(_mm_srli_epi64(hi, 57), 8)));
    lo = _mm_xor_si128(lo, fold);
    __m128i ov = _mm_srli_si128(_mm_srli_epi64(hi, 63), 8);
    ov = _mm_xor_si128(ov, _mm_srli_si128(_mm_srli_epi64(hi, 62), 8));
    ov = _mm_xor_si128(ov, _mm_srli_si128(_mm_srli_epi64(hi, 57), 8));
    __m128i f = _mm_xor_si128(ov, _mm_slli_epi64(ov, 1));
    f = _mm_xor_si128(f, _mm_slli_epi64(ov, 2));
    f = _mm_xor_si128(f, _mm_slli_epi64(ov, 7));
    return _mm_xor_si128(lo, f);
}

/* 4-way software pipelined GHASH. data is raw bytes; we brev inside. */
__attribute__((noinline))
__m128i ghash_pipe(const uint8_t *data, size_t nblocks, __m128i H) {
    __m128i P[4];
    P[0] = H;
    P[1] = reduce(clmul(H, H));
    P[2] = reduce(clmul(P[1], H));
    P[3] = reduce(clmul(P[2], H)); /* H^4 */
    __m128i y = _mm_setzero_si128();
    size_t i = 0;
    for (; i + 4 <= nblocks; i += 4) {
        __m128i b0 = brev(_mm_loadu_si128((const __m128i*)(data + i*16)));
        __m128i b1 = brev(_mm_loadu_si128((const __m128i*)(data + (i+1)*16)));
        __m128i b2 = brev(_mm_loadu_si128((const __m128i*)(data + (i+2)*16)));
        __m128i b3 = brev(_mm_loadu_si128((const __m128i*)(data + (i+3)*16)));
        /* issue all 5 carryless products before any reduction */
        prod_t p0 = clmul(y, P[3]);
        prod_t p1 = clmul(b0, P[3]);
        prod_t p2 = clmul(b1, P[2]);
        prod_t p3 = clmul(b2, P[1]);
        prod_t p4 = clmul(b3, P[0]);
        __m128i acc = reduce(p0);
        acc = _mm_xor_si128(acc, reduce(p1));
        acc = _mm_xor_si128(acc, reduce(p2));
        acc = _mm_xor_si128(acc, reduce(p3));
        acc = _mm_xor_si128(acc, reduce(p4));
        y = acc;
    }
    for (; i < nblocks; i++) {
        __m128i blk = brev(_mm_loadu_si128((const __m128i*)(data + i*16)));
        y = reduce(clmul(_mm_xor_si128(y, blk), H));
    }
    return y;
}

int main() {
    size_t n = 60*1024*1024/16;
    uint8_t *data = malloc(n*16);
    memset(data, 0x5a, n*16);
    __m128i H = _mm_set1_epi8(0x3c);
    struct timespec t0,t1;
    ghash_pipe(data, 1024, H);
    clock_gettime(CLOCK_MONOTONIC,&t0);
    volatile __m128i y = ghash_pipe(data, n, H);
    clock_gettime(CLOCK_MONOTONIC,&t1);
    double dt=(t1.tv_sec-t0.tv_sec)+(t1.tv_nsec-t0.tv_nsec)/1e9;
    printf("pipe %.4f s %.2f GB/s\n", dt, n*16.0/dt/1e9);
    (void)y; free(data);
    return 0;
}
EOF
