    __m128i hi = _mm_shuffle_epi8(lut, _mm_and_si128(_mm_srli_epi16(x, 4), _mm_set1_epi8(0x0f)));
    return _mm_or_si128(_mm_slli_epi16(lo, 4), hi);
}

/* Multiply two already-reversed elements. Hand-scheduled. */
static inline __m128i mul_asm(__m128i a, __m128i b) {
    __m128i lo, hi, mid, r;
    __asm__ volatile (
        "movdqa %1, %0\n\t"
        "pclmulqdq $0x00, %2, %0\n\t"      /* lo = a.lo*b.lo */
        "movdqa %1, %3\n\t"
        "pclmulqdq $0x11, %2, %3\n\t"      /* hi = a.hi*b.hi */
        "movdqa %1, %%xmm6\n\t"
        "pclmulqdq $0x01, %2, %%xmm6\n\t"
        "movdqa %1, %%xmm7\n\t"
        "pclmulqdq $0x10, %2, %%xmm7\n\t"
        "pxor %%xmm7, %%xmm6\n\t"          /* mid */
        "movdqa %%xmm6, %%xmm7\n\t"
        "pslldq $8, %%xmm7\n\t"
        "pxor %%xmm7, %0\n\t"              /* lo ^= mid<<64 */
        "psrldq $8, %%xmm6\n\t"
        "pxor %%xmm6, %3\n\t"              /* hi ^= mid>>64 */
        /* fold hi */
        "movdqa %3, %%xmm6\n\t"
        "psllq $1, %%xmm6\n\t"
        "movdqa %3, %%xmm7\n\t"
        "psrlq $63, %%xmm7\n\t"
        "pslldq $8, %%xmm7\n\t"
        "por %%xmm7, %%xmm6\n\t"
        "pxor %%xmm6, %0\n\t"
        "movdqa %3, %%xmm6\n\t"
        "psllq $2, %%xmm6\n\t"
        "movdqa %3, %%xmm7\n\t"
        "psrlq $62, %%xmm7\n\t"
        "pslldq $8, %%xmm7\n\t"
        "por %%xmm7, %%xmm6\n\t"
        "pxor %%xmm6, %0\n\t"
        "movdqa %3, %%xmm6\n\t"
        "psllq $7, %%xmm6\n\t"
        "movdqa %3, %%xmm7\n\t"
        "psrlq $57, %%xmm7\n\t"
        "pslldq $8, %%xmm7\n\t"
        "por %%xmm7, %%xmm6\n\t"
        "pxor %%xmm6, %0\n\t"
        "pxor %3, %0\n\t"                  /* lo ^= hi */
        /* overflow second fold: top bits of hi */
        "movdqa %3, %%xmm6\n\t"
        "psrlq $63, %%xmm6\n\t"
        "psrldq $8, %%xmm6\n\t"            /* >>127 */
        "movdqa %3, %%xmm7\n\t"
        "psrlq $62, %%xmm7\n\t"
        "psrldq $8, %%xmm7\n\t"
        "pxor %%xmm7, %%xmm6\n\t"
        "movdqa %3, %%xmm7\n\t"
        "psrlq $57, %%xmm7\n\t"
        "psrldq $8, %%xmm7\n\t"
        "pxor %%xmm7, %%xmm6\n\t"          /* ov */
        "movdqa %%xmm6, %%xmm7\n\t"
        "psllq $1, %%xmm7\n\t"
        "pxor %%xmm7, %%xmm6\n\t"
        "movdqa %%xmm6, %%xmm7\n\t"
        "psllq $1, %%xmm7\n\t"             /* ov<<2 = (ov ^ ov<<1)<<1 ^ something? NO. recompute. */
        "pxor %%xmm6, %0\n\t"
        : "=&x"(lo), "+x"(a), "+x"(b), "=&x"(hi)
        : 
        : "xmm6", "xmm7", "cc"
    );
    (void)r; (void)mid;
    return lo;
}

int main() {
    /* correctness vs known mul */
    __m128i a = _mm_set_epi64x(0x0123456789abcdefULL, 0xfedcba9876543210ULL);
    __m128i b = _mm_set_epi64x(0x1111111111111111ULL, 0x2222222222222222ULL);
    __m128i ar = brev(a), br = brev(b);
    __m128i r = mul_asm(ar, br);
    uint8_t out[16];
    _mm_storeu_si128((__m128i*)out, brev(r));
    for (int i = 0; i < 16; i++) printf("%02x", out[i]);
    printf("\n");
    return 0;
}
