static inline __m128i brev(__m128i x) {
    const __m128i lut = _mm_setr_epi8(0x00,0x08,0x04,0x0c,0x02,0x0a,0x06,0x0e,0x01,0x09,0x05,0x0d,0x03,0x0b,0x07,0x0f);
    __m128i lo = _mm_shuffle_epi8(lut, _mm_and_si128(x, _mm_set1_epi8(0x0f)));
    __m128i hi = _mm_shuffle_epi8(lut, _mm_and_si128(_mm_srli_epi16(x, 4), _mm_set1_epi8(0x0f)));
    return _mm_or_si128(_mm_slli_epi16(lo, 4), hi);
}

/* 128-bit left shift by a compile-time constant < 64, zero-filling. */
#define SHL128(v, s) _mm_or_si128(_mm_slli_epi64(v, s), _mm_slli_si128(_mm_srli_epi64(v, 64 - (s)), 8))

static inline __m128i mul(__m128i a, __m128i b) {
    __m128i lo = _mm_clmulepi64_si128(a, b, 0x00);
    __m128i hi = _mm_clmulepi64_si128(a, b, 0x11);
    __m128i mid = _mm_xor_si128(_mm_clmulepi64_si128(a, b, 0x01), _mm_clmulepi64_si128(a, b, 0x10));
    lo = _mm_xor_si128(lo, _mm_slli_si128(mid, 8));
    hi = _mm_xor_si128(hi, _mm_srli_si128(mid, 8));
    /* x^128 = x^7+x^2+x+1, plus second fold of the 7 overflow bits via SHL128 by 128+k == shift k of (hi>>121 etc). */
    __m128i h1 = SHL128(hi, 1);
    __m128i h2 = SHL128(hi, 2);
    __m128i h7 = SHL128(hi, 7);
    lo = _mm_xor_si128(lo, _mm_xor_si128(hi, _mm_xor_si128(h1, _mm_xor_si128(h2, h7))));
    /* overflow = bits shifted out of hi<<1, hi<<2, hi<<7 = hi >> 127, >>126, >>121, all in the top byte of the high lane */
    __m128i ov = _mm_srli_si128(hi, 15);          /* top byte in lane 0 */
    /* extract the relevant bits with shifts of that byte: bit7 of top byte is bit 127. */
    __m128i top = ov; /* byte value in low 8 bits */
    __m128i o1 = _mm_srli_epi16(top, 7);          /* >>127 */
    __m128i o2 = _mm_srli_epi16(top, 6);          /* >>126 */
    __m128i o7 = _mm_srli_epi16(top, 1);          /* >>121 */
    __m128i o = _mm_xor_si128(o1, _mm_xor_si128(o2, o7));
    lo = _mm_xor_si128(lo, o);
    lo = _mm_xor_si128(lo, _mm_slli_epi64(o, 1));
    lo = _mm_xor_si128(lo, _mm_slli_epi64(o, 2));
    lo = _mm_xor_si128(lo, _mm_slli_epi64(o, 7));
    return lo;
}

__attribute__((noinline))
__m128i ghash(const uint8_t *data, size_t nblocks, __m128i H) {
    __m128i y = _mm_setzero_si128();
    for (size_t i = 0; i < nblocks; i++) {
        __m128i blk = brev(_mm_loadu_si128((const __m128i *)(data + i * 16)));
        y = mul(_mm_xor_si128(y, blk), H);
    }
    return y;
}

int main() {
    size_t n = 60 * 1024 * 1024 / 16;
    uint8_t *data = malloc(n * 16);
    memset(data, 0x5a, n * 16);
    __m128i H = brev(_mm_set1_epi8(0x3c));
    ghash(data, 1024, H);
    struct timespec t0, t1;
    clock_gettime(CLOCK_MONOTONIC, &t0);
    volatile __m128i y = ghash(data, n, H);
    clock_gettime(CLOCK_MONOTONIC, &t1);
    double dt = (t1.tv_sec - t0.tv_sec) + (t1.tv_nsec - t0.tv_nsec) / 1e9;
    printf("%.4f s %.2f GB/s\n", dt, n * 16.0 / dt / 1e9);
    (void)y; free(data);
    return 0;
}
